// pushButtonTitle explains why push is disabled, rather than leaving a dead
// button with a generic tooltip.
func pushButtonTitle(inst GithubSyncStatus) string {
	if inst.PushBlocked {
		return inst.PushBlockedReason
	}
	return "Push strategy artifacts to GitHub"
}

